-- ---------------------------------------------------------------------
-- Step 0a — the helpers exist and this principal may execute them
-- EXPECTED: 4 rows. A missing function means the INSERTs below would
-- write rules the check runner cannot run.
-- ---------------------------------------------------------------------
SELECT routine_name, data_type
FROM   workspace.information_schema.routines
WHERE  routine_catalog = 'workspace' AND routine_schema = 'dq_triage'
  AND  routine_name IN ('dq_fn_is_blank_v1', 'dq_fn_is_valid_email_v1', 'dq_fn_is_au_mobile_v1', 'dq_fn_is_sentinel_v1')
ORDER  BY routine_name;

-- ---------------------------------------------------------------------
-- Step 0b — the helpers behave as 12_functions.sql documents
-- EXPECTED: true, true, NULL, true, false, true, NULL, true
-- The NULLs are load-bearing: is_blank_v1 absorbs NULL, the other three
-- propagate it, and count_if does not count a NULL predicate. If these
-- come back differently, STOP — violation counts will move.
-- ---------------------------------------------------------------------
SELECT
  workspace.dq_triage.dq_fn_is_blank_v1(NULL)              AS blank_null_true,
  workspace.dq_triage.dq_fn_is_blank_v1('  ')              AS blank_ws_true,
  workspace.dq_triage.dq_fn_is_valid_email_v1(NULL)        AS email_null_NULL,
  workspace.dq_triage.dq_fn_is_valid_email_v1('a.b@c.com') AS email_ok_true,
  workspace.dq_triage.dq_fn_is_valid_email_v1('a b@c.com') AS email_bad_false,
  workspace.dq_triage.dq_fn_is_au_mobile_v1('0412345678')  AS mobile_ok_true,
  workspace.dq_triage.dq_fn_is_sentinel_v1(NULL)           AS sentinel_null_NULL,
  workspace.dq_triage.dq_fn_is_sentinel_v1('n/a')          AS sentinel_na_true;

-- ---------------------------------------------------------------------
-- Step 0c — THE GUARD. Has this migration already run?
-- EXPECTED: already_adopted = 0. Any other number means some or all of
-- the INSERTs below have been applied. Re-running would stack another
-- version on top rather than failing. Read before you proceed.
-- ---------------------------------------------------------------------
SELECT count(*) AS already_adopted
FROM   workspace.dq_triage.dq_config_v_rule_registry_current
WHERE  contains(rule_expr, 'workspace.dq_triage.dq_fn_');

