-- =====================================================================
-- Step 2 — verification. All three are read-only.
-- =====================================================================

-- 2a — the current version of each rule now calls a helper.
-- EXPECTED: 13 rows, every verdict OK.
SELECT rule_id, rule_version, exp_version, status, rule_expr,
       CASE WHEN rule_expr = expected AND rule_version = exp_version
            THEN 'OK' ELSE 'MISMATCH' END AS verdict
FROM   (SELECT * FROM workspace.dq_triage.dq_config_v_rule_registry_current) c
JOIN   (VALUES
         ('CTCT_EML_FMT', 2, 'NOT workspace.dq_triage.dq_fn_is_valid_email_v1(EML_ID)'),
         ('CTCT_EML_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(EML_ID)'),
         ('CTCT_EML_STTS_CONSISTENT', 2, 'EML_STTS_CD = \'INVALID\' AND workspace.dq_triage.dq_fn_is_valid_email_v1(EML_ID)'),
         ('CTCT_EML_STTS_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(EML_STTS_CD)'),
         ('CTCT_IDNT_DOC_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(IDNT_DOC_1_NO)'),
         ('CTCT_MOBL_FMT', 2, 'NOT workspace.dq_triage.dq_fn_is_au_mobile_v1(MOBL_NO)'),
         ('CTCT_MOBL_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(MOBL_NO)'),
         ('SUBS_BNFT_TXT_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(BNFT_TXT)'),
         ('SUBS_IMEI_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(IMEI_ID)'),
         ('SUBS_MSISDN_FMT', 3, 'NOT workspace.dq_triage.dq_fn_is_au_mobile_v1(PRIM_RSRC_VALU_TXT)'),
         ('SUBS_MSISDN_SENTINEL', 2, 'workspace.dq_triage.dq_fn_is_sentinel_v1(PRIM_RSRC_VALU_TXT)'),
         ('SUBS_NTWK_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(NTWK_TECH_NM)'),
         ('SUBS_SIM_NOT_NULL', 2, 'workspace.dq_triage.dq_fn_is_blank_v1(SIM_SERL_ID)')
       ) AS e(rid, exp_version, expected) ON e.rid = c.rule_id
ORDER  BY verdict DESC, rule_id;

-- 2b — history survived. EXPECTED: no rule lost a version.
SELECT rule_id, count(*) AS versions, array_sort(collect_set(rule_version)) AS vs
FROM   workspace.dq_triage.dq_config_rule_registry
GROUP  BY rule_id HAVING count(*) > 1 ORDER BY rule_id;

-- 2c — THE ONE THAT MATTERS: the counts did not move.
-- Each helper is executed against the real rows and diffed against the
-- number the Python evaluator produced. EXPECTED: 13 PASS.
-- Two to read regardless of the verdict column — both must stay broken:
--   SUBS_IMEI_NOT_NULL       200
--   SUBS_BNFT_TXT_NOT_NULL   750  (shadow — measured, never raises)
SELECT rule_id, violations, expected, scanned, exp_scanned,
       CASE WHEN violations = expected AND scanned = exp_scanned
            THEN 'PASS' ELSE 'FAIL' END AS verdict
FROM (
  SELECT 'CTCT_EML_FMT'               AS rule_id, count_if(NOT workspace.dq_triage.dq_fn_is_valid_email_v1(EML_ID)) AS violations, 240 AS expected, count(*) AS scanned, 999 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c WHERE EML_ID IS NOT NULL AND trim(EML_ID) <> ''
  UNION ALL
  SELECT 'CTCT_EML_NOT_NULL'          AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(EML_ID)) AS violations, 1 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c
  UNION ALL
  SELECT 'CTCT_EML_STTS_CONSISTENT'   AS rule_id, count_if(EML_STTS_CD = 'INVALID' AND workspace.dq_triage.dq_fn_is_valid_email_v1(EML_ID)) AS violations, 0 AS expected, count(*) AS scanned, 999 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c WHERE EML_ID IS NOT NULL AND trim(EML_ID) <> ''
  UNION ALL
  SELECT 'CTCT_EML_STTS_NOT_NULL'     AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(EML_STTS_CD)) AS violations, 1 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c
  UNION ALL
  SELECT 'CTCT_IDNT_DOC_NOT_NULL'     AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(IDNT_DOC_1_NO)) AS violations, 0 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c WHERE IDNT_TYPE_1_CD IS NOT NULL AND trim(IDNT_TYPE_1_CD) <> ''
  UNION ALL
  SELECT 'CTCT_MOBL_FMT'              AS rule_id, count_if(NOT workspace.dq_triage.dq_fn_is_au_mobile_v1(MOBL_NO)) AS violations, 0 AS expected, count(*) AS scanned, 982 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c WHERE MOBL_NO IS NOT NULL AND trim(MOBL_NO) <> ''
  UNION ALL
  SELECT 'CTCT_MOBL_NOT_NULL'         AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(MOBL_NO)) AS violations, 18 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_ctct_c
  UNION ALL
  SELECT 'SUBS_BNFT_TXT_NOT_NULL'     AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(BNFT_TXT)) AS violations, 750 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_subs_c
  UNION ALL
  SELECT 'SUBS_IMEI_NOT_NULL'         AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(IMEI_ID)) AS violations, 200 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_subs_c
  UNION ALL
  SELECT 'SUBS_MSISDN_FMT'            AS rule_id, count_if(NOT workspace.dq_triage.dq_fn_is_au_mobile_v1(PRIM_RSRC_VALU_TXT)) AS violations, 12 AS expected, count(*) AS scanned, 800 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_subs_c WHERE PRIM_RSRC_TYPE_KEY = 1
  UNION ALL
  SELECT 'SUBS_MSISDN_SENTINEL'       AS rule_id, count_if(workspace.dq_triage.dq_fn_is_sentinel_v1(PRIM_RSRC_VALU_TXT)) AS violations, 12 AS expected, count(*) AS scanned, 800 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_subs_c WHERE PRIM_RSRC_TYPE_KEY = 1
  UNION ALL
  SELECT 'SUBS_NTWK_NOT_NULL'         AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(NTWK_TECH_NM)) AS violations, 16 AS expected, count(*) AS scanned, 1000 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_subs_c
  UNION ALL
  SELECT 'SUBS_SIM_NOT_NULL'          AS rule_id, count_if(workspace.dq_triage.dq_fn_is_blank_v1(SIM_SERL_ID)) AS violations, 0 AS expected, count(*) AS scanned, 800 AS exp_scanned
  FROM   workspace.dq_triage.dq_mock_subs_c WHERE PROD_TYPE_KEY <> 0
) ORDER BY verdict DESC, rule_id;

